-- 2026-11-02: add the reporting login, give every customer a tier from their lifetime spend, and index orders by time.
-- Run once with psql, as the owner of the orders database.

CREATE ROLE reporting LOGIN PASSWORD :'reporting_password';

BEGIN;

ALTER TABLE customers ADD COLUMN tier text NOT NULL DEFAULT 'standard';

UPDATE customers SET tier = 'gold' WHERE lifetime_cents >= 500000;

UPDATE customers SET tier = 'silver' WHERE lifetime_cents >= 100000 AND tier = 'standard';

CREATE INDEX orders_placed_at_idx ON orders (placed_at);

COMMIT;

-- Orders placed on one day.
SELECT id, customer_id
FROM orders
WHERE placed_at >= :'day'
  AND placed_at < :'day'::timestamptz + interval '1 day';

-- Customers who were not referred by the partner programme.
SELECT id, email
FROM customers
WHERE referrer_id IS DISTINCT FROM :partner_id;
